Create a data model to represent the match, sets, games, and points.

```swift
import Foundation

enum PointDetail {
    case winner
    case unforcedError
    case forcedError
    case ace
    case returnWinner
    case serveWinner
}

struct Point {
    var detail: PointDetail
}

struct Game {
    var points: [Point] = []
    var player1Score: Int = 0
    var player2Score: Int = 0
}

struct Set {
    var games: [Game] = []
    var player1GamesWon: Int = 0
    var player2GamesWon: Int = 0
}

class Match: ObservableObject {
    @Published var sets: [Set] = [Set()]
    @Published var currentSetIndex: Int = 0

    func addPoint(toPlayer1: Bool, detail: PointDetail) {
        var currentSet = sets[currentSetIndex]
        var currentGame = currentSet.games.last ?? Game()

        let point = Point(detail: detail)
        currentGame.points.append(point)

        if toPlayer1 {
            currentGame.player1Score += 1
        } else {
            currentGame.player2Score += 1
        }

        // Check if the game is won
        if currentGame.player1Score >= 4 && currentGame.player1Score - currentGame.player2Score >= 2 {
            currentSet.player1GamesWon += 1
            currentSet.games.append(Game())
        } else if currentGame.player2Score >= 4 && currentGame.player2Score - currentGame.player1Score >= 2 {
            currentSet.player2GamesWon += 1
            currentSet.games.append(Game())
        } else {
            currentSet.games[currentSet.games.count - 1] = currentGame
        }

        // Check if the set is won
        if currentSet.player1GamesWon >= 6 && currentSet.player1GamesWon - currentSet.player2GamesWon >= 2 {
            if currentSetIndex < 2 {
                sets.append(Set())
                currentSetIndex += 1
            }
        } else if currentSet.player2GamesWon >= 6 && currentSet.player2GamesWon - currentSet.player1GamesWon >= 2 {
            if currentSetIndex < 2 {
                sets.append(Set())
                currentSetIndex += 1
            }
        }

        sets[currentSetIndex] = currentSet
    }
}
```

