fn sendControllerState(sock: posix.fd_t, addr: *const net.Address, controllerState: []const i16) !void {
    const sockaddr = &addr.any;
    const addrlen = addr.getOsSockLen();
    var buffer: [BUFFER_SIZE]u8 = undefined;
    var bufferIndex: usize = 0;

    for (controllerState) |value, index| {
        if (bufferIndex + 2 * @sizeOf(i16) > buffer.len) break; // Ensure we don't overflow the buffer
        const eventIndex = @intCast(i16, index);
        const eventValue = value;

        // Copy event index and value into the buffer
        @memcpy(&buffer[bufferIndex], @ptrCast([*]const u8, &eventIndex), @sizeOf(i16));
        bufferIndex += @sizeOf(i16);
        @memcpy(&buffer[bufferIndex], @ptrCast([*]const u8, &eventValue), @sizeOf(i16));
        bufferIndex += @sizeOf(i16);
    }

    const ret = try posix.sendto(sock, buffer[0..bufferIndex], 0, sockaddr, addrlen);
    if (ret != bufferIndex) {
        std.log.warn("Warning: Not all data was sent. Expected to send {}, but sent {}\n", .{ bufferIndex, ret });
    }
}
```

