  <script>
    class XDetails extends HTMLElement {
      constructor() {
        super();
        this.attachShadow({ mode: 'open' });

        this.shadowRoot.innerHTML = `
          <style>
            :host {
              display: block;
              border: 1px solid #ccc;
              padding: 10px;
              border-radius: 5px;
            }
            .header {
              display: flex;
              align-items: center;
              cursor: pointer;
              font-size: 1.2em;
              border-bottom: 1px solid #ccc;
              padding-bottom: 5px;
              margin-bottom: 10px;
            }
            .toggle {
              display: inline-block;
              width: 20px;
              height: 20px;
              line-height: 20px;
              text-align: center;
              border: 1px solid #000;
              margin-right: 10px;
              user-select: none;
            }
            .intro {
              margin-bottom: 10px;
            }
            .details {
              display: none;
            }
            .expand-button {
              display: none;
              cursor: pointer;
              color: blue;
              text-decoration: underline;
            }
          </style>
          <div class="header">
            <div class="toggle">+</div>
            <slot name="header"></slot>
          </div>
          <div class="intro">
            <slot name="intro"></slot>
          </div>
          <div class="details">
            <slot name="details"></slot>
          </div>
          <div class="expand-button">Expand more</div>
        `;

        this.isExpanded = false;
        this.toggleButton = this.shadowRoot.querySelector('.toggle');
        this.detailsSection = this.shadowRoot.querySelector('.details');
        this.expandButton = this.shadowRoot.querySelector('.expand-button');

        this.toggleButton.addEventListener('click', () => this.toggleDetails());
        this.expandButton.addEventListener('click', () => this.toggleDetails());
