### Step 3: Implement the Controller

In `src/Controller/ArticleListController.php`, implement the controller logic:

```php
<?php

namespace Drupal\custom_article_list\Controller;

use Drupal\Core\Controller\ControllerBase;
use Drupal\node\Entity\Node;
use Drupal\taxonomy\Entity\Term;
use Symfony\Component\DependencyInjection\ContainerInterface;
use Drupal\Core\Entity\EntityTypeManagerInterface;

/**
 * Returns responses for Custom Article List routes.
 */
class ArticleListController extends ControllerBase {

  /**
   * The entity type manager service.
   *
   * @var \Drupal\Core\Entity\EntityTypeManagerInterface
   */
  protected $entityTypeManager;

  /**
   * Constructs a new ArticleListController object.
   *
   * @param \Drupal\Core\Entity\EntityTypeManagerInterface $entity_type_manager
   *   The entity type manager service.
   */
  public function __construct(EntityTypeManagerInterface $entity_type_manager) {
    $this->entityTypeManager = $entity_type_manager;
  }

  /**
   * {@inheritdoc}
   */
  public static function create(ContainerInterface $container) {
    return new static(
      $container->get('entity_type.manager')
    );
  }

  /**
   * Displays a teaser list of articles tagged with 'foobar'.
   *
   * @return array
   *   A render array.
   */
  public function teaserList() {
    // Load the taxonomy term 'foobar'.
    $term = $this->entityTypeManager->getStorage('taxonomy_term')->loadByProperties(['name' => 'foobar']);
    $term = reset($term);

    if (!$term) {
      return [
        '#markup' => $this->t('No articles found with the tag "foobar".'),
      ];
    }

    // Query for article nodes tagged with 'foobar'.
    $query = $this->entityTypeManager->getStorage('node')->getQuery();
    $nids = $query
      ->condition('type', 'article')
      ->condition('status', 1)
      ->condition('field_tags.target_id', $term->id())
      ->sort('created', 'DESC')
      ->execute();

    if (empty($nids)) {
      return [
        '#markup' => $this->t('No articles found with the tag "foobar".'),
      ];
    }

    // Load the nodes.
    $nodes = $this->entityTypeManager->getStorage('node')->loadMultiple($nids);

    // Build the render array.
    $items = [];
    foreach ($nodes as $node) {
      $items[] = [
        '#theme' => 'node',
        '#node' => $node,
        '#view_mode' => 'teaser',
      ];
    }

    return [
      '#theme' => 'item_list',
      '#items' => $items,
      '#attributes' => ['class' => ['list-group']],
    ];
  }

}
```

