To refactor the code using best practices and following SOLID principles, we can break down the responsibilities into separate classes and functions. This will make the code more maintainable, testable, and easier to understand. We'll use the Factory Method design pattern to create users and update their permissions. Here's how you can refactor the code in TypeScript:

```typescript
// userFactory.ts
class UserFactory {
  constructor(private request: any) {}

  async createUser(payload: any): Promise<string> {
    const res = await this.request.post("/users/v2/create", payload);
    if (res.status() !== 201) {
      throw new Error('Failed to create user');
    }
    const json = await res.json();
    return json.id;
  }

  async updateUserPermissions(userId: string, permissionPayload: any): Promise<{ username: string, password: string }> {
    const updatedPayload = { ...permissionPayload, id: userId };
    const res = await this.request.post("/users/v2/permissions", updatedPayload);
    if (res.status() !== 200) {
      throw new Error('Failed to update user permissions');
    }
    return await res.json();
  }
}

// loginPage.ts
