import java.util.ArrayList;
import java.util.List;

public class Staircase {

    public static void main(String[] args) {
        int n = 4; // 你可以改变这个值来测试不同的台阶数
        List<List<Integer>> ways = findWays(n);
        System.out.println("总共有 " + ways.size() + " 种方法。");
        for (List<Integer> way : ways) {
            System.out.println(way);
        }
    }

    public static List<List<Integer>> findWays(int n) {
        List<List<Integer>> result = new ArrayList<>();
        findWaysHelper(n, new ArrayList<>(), result);
        return result;
    }

    private static void findWaysHelper(int n, List<Integer> current, List<List<Integer>> result) {
        if (n == 0) {
            result.add(new ArrayList<>(current));
            return;
        }
        if (n < 0) {
            return;
        }

        // 选择走一步
        current.add(1);
        findWaysHelper(n - 1, current, result);
        current.remove(current.size() - 1);

        // 选择走两步
        current.add(2);
        findWaysHelper(n - 2, current, result);
        current.remove(current.size() - 1);
    }
}
